    addEntries(menu && menu.files);
    addEntries(menu && menu.menu_files);
    addEntries(menu && menu.file_urls);
    addEntries(menu && menu.images, "image");
    addEntries(menu && menu.menu_images, "image");
    addEntries(menu && menu.image_files, "image");
    addEntries(menu && menu.image_file_urls, "image");
    addEntries(menu && menu.png_url, "image");
    addEntries(menu && menu.pdf_files, "pdf");
    addEntries(menu && menu.pdf_file_urls, "pdf");
    addEntries(menu && menu.pdf_url, "pdf");
    addEntries(menu && menu.primary_image_url, "image");
    addEntries(menu && menu.primary_pdf_url, "pdf");
