            var passwordParams = resolvePasswordParams(invitationContext, null, form);
            var resolvedInvitationUuid = await ensureInvitationUuid(invitationContext, passwordParams);
            var wishInvitationUuid = toTrimmedString(resolvedInvitationUuid || invitationContext.uuid);

